<script setup>
import { computed } from 'vue'
import { targetProjection, formatTargetDuration } from '../composables/useServiceTargetClock.js'
const props = defineProps({ record:{type:Object,required:true}, progress:{type:Object,default:null}, compact:{type:Boolean,default:false} })
const target = computed(() => props.record.service_target)
const view = computed(() => props.progress || targetProjection(props.record))
const statuses = {running:'目标进行中',overdue:'服务端已确认超时',completed:'已完成目标',late_completed:'超时后完成目标',withdrawn:'已撤回，目标停止',pending:'目标待定',legacy_unresolved:'历史目标无法回溯'}
const bases = {open_at_submission:'提交时空间开放，按经过时间计算；跨闭馆不暂停',next_room_opening:'按提交时已知的下次空间开放起点计算',service_24h:'提交起24小时内首次正式反馈',legacy_service_derived:'根据历史提交时刻派生，非历史已保存目标',legacy_occupation_unresolved:'缺少提交时开放依据，不以当前日历补造历史目标'}
</script>
<template><section v-if="target" class="service-target" :class="{'target-overdue':target.status==='overdue'||target.status==='late_completed','target-pending':view?.awaiting_check}" :data-target-status="target.status"><h4>{{ target.kind==='acceptance'?'受理并开始核查目标':'首次正式反馈目标' }} · {{ statuses[target.status] || target.status }}</h4><p>{{ target.kind==='acceptance'?'15分钟是接单开始核查目标，不表示到场或解决。':'24小时是首次正式反馈目标，受理和核实不替代正式反馈。' }}</p><p v-if="target.due_at">冻结目标时刻：{{ target.due_at }}（{{ record.campus_zone || 'Asia/Shanghai' }}）</p><p v-if="target.status==='running' && view?.remaining_seconds!==null">{{ progress?'估算剩余':'服务端读取时剩余' }}：{{ formatTargetDuration(view.remaining_seconds) }}<span v-if="view.awaiting_check">；本地估算已到目标时刻，待服务端核对，请刷新读取。此处不自行认定超时已登记。</span></p><p v-if="target.status==='overdue'">服务端确认超时<span v-if="view?.overdue_seconds!==null">，{{ progress?'估算已超出':'读取时已超出' }}{{ formatTargetDuration(view.overdue_seconds) }}</span>；这是管理服务目标，不计用户违规。</p><p v-if="target.completed_at">目标完成：{{ target.completed_at }}；{{ target.was_late===true?'超过或恰好到目标时刻完成':target.was_late===false?'在目标时刻前完成':'历史依据不足，未判定是否按时' }}。</p><p v-if="target.stopped_at">停止：{{ target.stopped_at }}；撤回停止不等于目标已完成。</p><p>{{ target.reason || bases[target.basis] || '未提供目标计算依据' }}</p><template v-if="!compact"><p v-if="target.reason && bases[target.basis]">依据：{{ bases[target.basis] }}</p><p v-if="target.anchor_at">冻结起算：{{ target.anchor_at }}；计算登记：{{ target.calculated_at }}<span v-if="target.room_version!==null && target.room_version!==undefined">；当时空间版本{{ target.room_version }}</span>。后续资源变更不自动顺延此目标。</p><p v-if="target.overdue_event">超时发生：{{ target.overdue_event.occurred_at }}；实际检测登记：{{ target.overdue_event.detected_at }}；{{ target.overdue_event.source==='legacy_derived'?'历史派生目标首次检测':'新提交目标检测' }}，不表示过去已发出提醒。</p></template></section><p v-else class="service-target-missing">服务端尚未提供处理目标，不能推定期限或完成情况。</p></template>
<style scoped>.service-target{display:grid;gap:7px;padding:12px;border:1px solid var(--border);border-radius:var(--r-md);min-width:0;overflow-wrap:anywhere;background:var(--surface-2)}.service-target h4,.service-target p{margin:0}.target-overdue,.target-pending{border-color:var(--warning,#c28719)}.service-target-missing{color:var(--text-2)}</style>
